   5 /// <summary>
   6 /// T2-T4: what the Tanuki would copy at one moment of a run: the slot and special it takes from Ryo and
   7 /// the level it takes it at. The copy never has a modifier and never the Lv 3 evolution (T4), so there
   8 /// is no modifier member here and <see cref="Build"/> stops at the last level that is not an evolution.
   9 /// </summary>
  10 /// <param name="Slot">The slot the special sits in on Ryo's side (T2: only specials in a slot count).</param>
  11 /// <param name="Data">The copied special's data: the move itself, shared with Ryo.</param>
  12 /// <param name="Level">Ryo's level of the special at the moment of asking (T4: "at Ryo's level").</param>
  13 public sealed record CopyTarget(SpecialSlot Slot, SpecialData Data, int Level)
  14 {
  15 	/// <summary>
  16 	/// T4: the level whose frame data the copy runs. Ryo's level, except that Lv 3 is the evolution (A4)
  17 	/// and the copy never gets it, so a copy of a Lv 3 special runs the Lv 2 tuning only.
  18 	/// </summary>
  19 	public int MoveLevel => Math.Min(Level, CopyRule.HighestUnevolvedLevel);
  20 
  21 	/// <summary>
  22 	/// T4: the copy's move, built from data at <see cref="MoveLevel"/> with no modifier. Ryo's own version
  23 	/// is <c>Data.Build(Level, ex, hisModifier, config)</c>; this one never sees his modifier or evolution.
  24 	/// </summary>
  25 	public MoveData Build(bool ex = false) => Data.Build(MoveLevel, ex, null, null);
  26 }
  27 
  28 /// <summary>
  29 /// T2-T4, GDD 5.3: the Tanuki's copy target, answered from the run state alone (pure C#, deterministic,
  30 /// reads only). Nothing here locks the target (T1) or builds the Tanuki's fighter (T0).
  31 /// </summary>
  32 public static class CopyRule
  33 {
  34 	/// <summary>T4 with A4: Lv 3 is the evolution, so Lv 2 is the highest level a copy's frame data reaches.</summary>
  35 	public const int HighestUnevolvedLevel = 2;
  36 
  37 	/// <summary>
  38 	/// T2: the highest-level special currently in a slot, whatever kind of move it is (throws included; there
  39 	/// is no filter). A sold or replaced special is no longer in a slot, so it can't be chosen.
  40 	/// T3: among equal levels the one levelled most recently (<see cref="RunState.LevelledOrder"/>), then the
  41 	/// lower slot. Null only when no slot holds a special.
  42 	/// </summary>
  43 	public static CopyTarget? Target(RunState run)
  44 	{
  45 		if (run is null) throw new ArgumentNullException(nameof(run));
  46 		OwnedSpecial? best = null;
  47 		SpecialSlot bestSlot = SpecialSlot.None;
  48 		int bestOrder = 0;
  49 		// Owned walks slots A-D upwards and every comparison is strict, so a full tie keeps the lower slot (T3).
  50 		foreach (var (slot, s) in run.Owned)
  51 		{
  52 			int order = run.LevelledOrder(slot);
  53 			bool better = best is null
  54 				|| s.Level > best.Level                            // T2: highest level
  55 				|| (s.Level == best.Level && order < bestOrder);   // T3: most recently levelled
  56 			if (!better) continue;
  57 			best = s;
  58 			bestSlot = slot;
  59 			bestOrder = order;
  60 		}
  61 		return best is null ? null : new CopyTarget(bestSlot, best.Data, best.Level);
  62 	}
  63 }
  64 

