   6 /// <summary>A special Ryo owns this run: its level (A3) and its one modifier (A2).</summary>
   7 public sealed record OwnedSpecial(SpecialData Data, int Level, ModifierData? Modifier);
   8 
   9 /// <summary>
  10 /// YOK-47: Ryo's run state between duels (pure C#, deterministic): health (C1 carries across the run),
  11 /// slots A-D and, since YOK-76, the run map (<see cref="Map"/>). The next fight reads it through <see cref="MatchConfig"/> and <see cref="ApplyTo"/>.
  12 /// </summary>
  13 public sealed class RunState
  14 {
  15 	public const int MaxHealth = 1000; // C1
  16 	public const int BindHeal = 50;    // R3
  17 
  18 	readonly OwnedSpecial?[] _slots = new OwnedSpecial?[5];
  19 
  20 	/// <summary>
  21 	/// T3: per slot, the rank of its special's latest level-up among the specials now in a slot (0 = never
  22 	/// levelled, 1 = earliest, higher = more recent). Kept compact by <see cref="CompactLevelled"/> after
  23 	/// every change, so a value never exceeds the number of slots and no arithmetic on it can overflow.
  24 	/// </summary>
  25 	readonly int[] _levelledAt = new int[5];
  26 
  27 	/// <summary>
  28 	/// T3: how recently the special now in <paramref name="slot"/> gained a level, as a rank among the
  29 	/// specials currently in a slot: 1 = the earliest of them, higher = more recent, 0 = it has not levelled
  30 	/// this run (or the slot is empty). It belongs to the special, not the slot: a replaced special's level-up
  31 	/// is dropped with it (T2). Part of <see cref="StateHash"/>; restored by <see cref="RestoreLevelledOrder"/>.
  32 	/// </summary>
  33 	public int LevelledOrder(SpecialSlot slot)
  34 	{
  35 		int at = _slots[(int)slot] is null ? 0 : _levelledAt[(int)slot];
  36 		if (at == 0) return 0;
  37 		int rank = 1;
  38 		for (int i = 1; i < _slots.Length; i++)
  39 			if (_slots[i] is not null && _levelledAt[i] > 0 && _levelledAt[i] < at) rank++;
  40 		return rank;
  41 	}
  42 
  43 	/// <summary>T3: rewrites the stamps as their ranks (1..4, 0 for never levelled or empty); the order is unchanged.</summary>
  44 	void CompactLevelled()
  45 	{
  46 		var ranks = new int[_levelledAt.Length];
  47 		for (int i = 1; i < ranks.Length; i++) ranks[i] = LevelledOrder((SpecialSlot)i);
  48 		for (int i = 1; i < ranks.Length; i++) _levelledAt[i] = ranks[i];
  49 	}
  50 
  51 	/// <summary>
  52 	/// T3: puts back the level-up order of a saved run, slots A-D, as <see cref="LevelledOrder"/> reported it.
  53 	/// Only the relative order of the non-zero values matters: they are stored as ranks, never as given, so
  54 	/// any positive magnitude is safe. Call it after the slots and levels are back, so a restored run does not
  55 	/// depend on replaying its picks in the original sequence. Throws, changing nothing, when the values can't
  56 	/// describe these slots: negative, two slots sharing a non-zero value, non-zero for an empty slot or a
  57 	/// Lv 1 special, or 0 for a special above Lv 1.
  58 	/// </summary>
  59 	public void RestoreLevelledOrder(int a, int b, int c, int d)
  60 	{
  61 		var orders = new[] { 0, a, b, c, d };
  62 		for (int i = 1; i < _slots.Length; i++)
  63 		{
  64 			int o = orders[i];
  65 			if (o < 0) throw new ArgumentException($"slot {(SpecialSlot)i}: level-up order can't be negative");
  66 			bool levelled = _slots[i] is { } s && s.Level > 1;
  67 			if ((o > 0) != levelled)
  68 				throw new ArgumentException($"slot {(SpecialSlot)i}: level-up order {o} doesn't match what the slot holds");
  69 			for (int j = 1; j < i; j++)
  70 				if (o > 0 && orders[j] == o)
  71 					throw new ArgumentException($"slots {(SpecialSlot)j} and {(SpecialSlot)i} share level-up order {o}");
  72 		}
  73 		for (int i = 1; i < _slots.Length; i++) _levelledAt[i] = orders[i];
  74 		CompactLevelled(); // only compared, never added to, before this
  75 	}
  76 
  77 	public int Health { get; private set; } = MaxHealth;
  78 
  79 	/// <summary>YOK-76: where Ryo is on the run map (null = a run without a map, e.g. the two-duel demo).</summary>
  80 	public RunMap? Map { get; private set; }
  81 
  82 	/// <summary>Starts this run's map from the first row. Health and slots are untouched.</summary>
  83 	public RunMap StartMap(MapGraph graph) => Map = new RunMap(graph);
  84 
  85 	/// <summary>Puts back a walk in progress (<see cref="RunMap.Restore"/>), or removes the map with null.</summary>
  86 	public void SetMap(RunMap? map) => Map = map;
  87 
  88 	public OwnedSpecial? this[SpecialSlot slot] => _slots[(int)slot];
  89 
  90 	/// <summary>Owned specials in slot order A-D.</summary>
  91 	public IEnumerable<(SpecialSlot Slot, OwnedSpecial Special)> Owned
  92 	{
  93 		get
  94 		{
  95 			for (int i = 1; i < _slots.Length; i++)
  96 				if (_slots[i] is { } s) yield return ((SpecialSlot)i, s);
  97 		}
  98 	}
