  11 /// slots A-D and, since YOK-76, the run map (<see cref="Map"/>). The next fight reads it through <see cref="MatchConfig"/> and <see cref="ApplyTo"/>.
  12 /// </summary>
  13 public sealed class RunState
  14 {
  15 	public const int MaxHealth = 1000; // C1
  16 	public const int BindHeal = 50;    // R3
  17 
  18 	readonly OwnedSpecial?[] _slots = new OwnedSpecial?[5];
  19 
  20 	/// <summary>
  21 	/// T3: per slot, the rank of its special's latest level-up among the specials now in a slot (0 = never
  22 	/// levelled, 1 = earliest, higher = more recent). Kept compact by <see cref="CompactLevelled"/> after
  23 	/// every change, so a value never exceeds the number of slots and no arithmetic on it can overflow.
  24 	/// </summary>
  25 	readonly int[] _levelledAt = new int[5];
  26 
  27 	/// <summary>
  28 	/// T3: how recently the special now in <paramref name="slot"/> gained a level, as a rank among the
  29 	/// specials currently in a slot: 1 = the earliest of them, higher = more recent, 0 = it has not levelled
  30 	/// this run (or the slot is empty). It belongs to the special, not the slot: a replaced special's level-up
  31 	/// is dropped with it (T2). Part of <see cref="StateHash"/>; restored by <see cref="RestoreLevelledOrder"/>.
  32 	/// </summary>
  33 	public int LevelledOrder(SpecialSlot slot)
  34 	{
  35 		int at = _slots[(int)slot] is null ? 0 : _levelledAt[(int)slot];
  36 		if (at == 0) return 0;
  37 		int rank = 1;
  38 		for (int i = 1; i < _slots.Length; i++)
  39 			if (_slots[i] is not null && _levelledAt[i] > 0 && _levelledAt[i] < at) rank++;
  40 		return rank;
  41 	}
  42 
  43 	/// <summary>T3: rewrites the stamps as their ranks (1..4, 0 for never levelled or empty); the order is unchanged.</summary>
  44 	void CompactLevelled()
  45 	{
  46 		var ranks = new int[_levelledAt.Length];
  47 		for (int i = 1; i < ranks.Length; i++) ranks[i] = LevelledOrder((SpecialSlot)i);
  48 		for (int i = 1; i < ranks.Length; i++) _levelledAt[i] = ranks[i];
  49 	}
  50 
  51 	/// <summary>
  52 	/// T3: puts back the level-up order of a saved run, slots A-D, as <see cref="LevelledOrder"/> reported it.
  53 	/// Only the relative order of the non-zero values matters: they are stored as ranks, never as given, so
  54 	/// any positive magnitude is safe. Call it after the slots and levels are back, so a restored run does not
  55 	/// depend on replaying its picks in the original sequence. Throws, changing nothing, when the values can't
  56 	/// describe these slots: negative, two slots sharing a non-zero value, non-zero for an empty slot or a
  57 	/// Lv 1 special, or 0 for a special above Lv 1.
  58 	/// </summary>
  59 	public void RestoreLevelledOrder(int a, int b, int c, int d)
  60 	{
  61 		var orders = new[] { 0, a, b, c, d };
  62 		for (int i = 1; i < _slots.Length; i++)
  63 		{
  64 			int o = orders[i];
  65 			if (o < 0) throw new ArgumentException($"slot {(SpecialSlot)i}: level-up order can't be negative");
  66 			bool levelled = _slots[i] is { } s && s.Level > 1;
  67 			if ((o > 0) != levelled)
  68 				throw new ArgumentException($"slot {(SpecialSlot)i}: level-up order {o} doesn't match what the slot holds");
  69 			for (int j = 1; j < i; j++)
  70 				if (o > 0 && orders[j] == o)
  71 					throw new ArgumentException($"slots {(SpecialSlot)j} and {(SpecialSlot)i} share level-up order {o}");
  72 		}
  73 		for (int i = 1; i < _slots.Length; i++) _levelledAt[i] = orders[i];
  74 		CompactLevelled(); // only compared, never added to, before this
  75 	}
  76 
  77 	public int Health { get; private set; } = MaxHealth;
  78 
  79 	/// <summary>YOK-76: where Ryo is on the run map (null = a run without a map, e.g. the two-duel demo).</summary>
  80 	public RunMap? Map { get; private set; }
  81 
  82 	/// <summary>Starts this run's map from the first row. Health and slots are untouched.</summary>
  83 	public RunMap StartMap(MapGraph graph) => Map = new RunMap(graph);
  84 
  85 	/// <summary>Puts back a walk in progress (<see cref="RunMap.Restore"/>), or removes the map with null.</summary>
  86 	public void SetMap(RunMap? map) => Map = map;
  87 
  88 	public OwnedSpecial? this[SpecialSlot slot] => _slots[(int)slot];
  89 
  90 	/// <summary>Owned specials in slot order A-D.</summary>
  91 	public IEnumerable<(SpecialSlot Slot, OwnedSpecial Special)> Owned
  92 	{
  93 		get
  94 		{
  95 			for (int i = 1; i < _slots.Length; i++)
  96 				if (_slots[i] is { } s) yield return ((SpecialSlot)i, s);
  97 		}
  98 	}
  99 
 100 	public bool Owns(string specialId)
 101 	{
 102 		foreach (var (_, s) in Owned) if (s.Data.Id == specialId) return true;
 103 		return false;
 104 	}
 105 
 106 	/// <summary>A1: a new run = the starters at Lv 1 in their own slots, full health.</summary>
 107 	public static RunState NewRun(AbilityPool pool, MapGraph? map = null)
 108 	{
 109 		var run = new RunState();
 110 		if (map is not null) run.StartMap(map);
 111 		foreach (var s in pool.Starters)
 112 			if (run._slots[(int)s.Slot] is null) run._slots[(int)s.Slot] = new OwnedSpecial(s, 1, null);
 113 		return run;
 114 	}
 115 
 116 	/// <summary>
 117 	/// A3: a newly drafted special goes in its own slot at Lv 1; drafting one already owned levels it up.
 118 	/// A different special in that slot is replaced and its levels and modifier are lost (A6). Returns the slot.
 119 	/// </summary>
 120 	public SpecialSlot Equip(SpecialData data)
 121 	{
 122 		if (_slots[(int)data.Slot] is { } cur && cur.Data.Id == data.Id) { LevelUp(data.Slot); return data.Slot; }
 123 		_slots[(int)data.Slot] = new OwnedSpecial(data, 1, null);
 124 		_levelledAt[(int)data.Slot] = 0; // T2/T3: the replaced special's level-up no longer counts
 125 		CompactLevelled();
 126 		return data.Slot;
 127 	}
 128 
 129 	public bool CanLevelUp(SpecialSlot slot) => this[slot] is { } s && s.Level < Math.Min(3, s.Data.MaxLevel);
 130 
 131 	/// <summary>A3/A4: one level up, the step from the special's data (Lv 2 tuning, Lv 3 evolution). Returns the new level.</summary>
 132 	public int LevelUp(SpecialSlot slot)
 133 	{
 134 		var s = this[slot] ?? throw new InvalidOperationException($"slot {slot} is empty");
 135 		if (!CanLevelUp(slot)) throw new InvalidOperationException($"{s.Data.Id} has no level above {s.Level}");
 136 		_slots[(int)slot] = s with { Level = s.Level + 1 };
 137 		CompactLevelled(); // stamps are 0..4 from here, so the +1 below can't overflow
 138 		int latest = 0;
 139 		for (int i = 1; i < _levelledAt.Length; i++) latest = Math.Max(latest, _levelledAt[i]);
 140 		_levelledAt[(int)slot] = latest + 1; // T3: this special is now the most recently levelled
 141 		CompactLevelled();
 142 		return s.Level + 1;
 143 	}
 144 
 145 	/// <summary>A2: one modifier per special; the special must meet the modifier's applies_to.</summary>
 146 	public bool CanAttach(SpecialSlot slot, ModifierData modifier) =>
 147 		this[slot] is { } s && s.Modifier is null && modifier.AppliesTo(s.Data);
 148 
 149 	public void Attach(SpecialSlot slot, ModifierData modifier)
 150 	{
 151 		if (!CanAttach(slot, modifier)) throw new InvalidOperationException($"{modifier.Id} can't attach to slot {slot}");
 152 		_slots[(int)slot] = this[slot]! with { Modifier = modifier };
 153 	}
 154 
 155 	/// <summary>R3: after a won duel the yokai is bound: health left + 50, capped at 1,000.</summary>
 156 	public void AfterDuel(int healthLeft, bool bound = true) =>
 157 		Health = Math.Min(MaxHealth, Math.Max(0, healthLeft) + (bound ? BindHeal : 0));
 158 
 159 	/// <summary>Merchant / dojo heals and other run events (clamped 0..1,000).</summary>
 160 	public void SetHealth(int health) => Health = Math.Clamp(health, 0, MaxHealth);
 161 
 162 	/// <summary>The next fight's config: Ryo (P1) starts with the carried health.</summary>
 163 	public SimConfig MatchConfig(SimConfig? baseConfig = null) =>
 164 		(baseConfig ?? SimConfig.Default) with { P1MaxHealth = MaxHealth, P1StartHealth = Health };
 165 
 166 	/// <summary>Puts the run's specials (levels, modifiers) on the fighter, replacing whatever it had.</summary>
 167 	public void ApplyTo(Fighter f, SimConfig? config = null)
 168 	{
 169 		for (int i = 1; i < _slots.Length; i++)
 170 		{
 171 			if (_slots[i] is { } s) f.Equip((SpecialSlot)i, s.Data, s.Level, s.Modifier, config);
 172 			else f.Unequip((SpecialSlot)i);
 173 		}
 174 	}
 175 
 176 	public ulong StateHash()
 177 	{
 178 		ulong h = Fnv.Mix(Fnv.Offset, Health);
 179 		for (int i = 1; i < _slots.Length; i++)
 180 		{
 181 			h = Fnv.MixString(h, _slots[i]?.Data.Id ?? "");
 182 			h = Fnv.Mix(h, _slots[i]?.Level ?? 0);
 183 			h = Fnv.MixString(h, _slots[i]?.Modifier?.Id ?? "");
 184 		}
 185 		// T3: the level-up order decides the Tanuki's copy target, so it is run state. A run in which no
 186 		// special in a slot has levelled keeps the hash it had before the copy rule (recorded replays).
 187 		bool anyLevelled = false;
 188 		for (int i = 1; i < _slots.Length; i++) anyLevelled |= LevelledOrder((SpecialSlot)i) > 0;
 189 		if (anyLevelled)
 190 			for (int i = 1; i < _slots.Length; i++) h = Fnv.Mix(h, LevelledOrder((SpecialSlot)i));
 191 		if (Map is not null) // a run without a map keeps the hash it had before YOK-76 (recorded replays)
 192 		{
 193 			ulong m = Map.StateHash();
 194 			h = Fnv.Mix(h, unchecked((int)m));
 195 			h = Fnv.Mix(h, unchecked((int)(m >> 32)));
 196 		}
 197 		return h;
 198 	}
 199 }
