  61 		var orders = new[] { 0, a, b, c, d };
  62 		for (int i = 1; i < _slots.Length; i++)
  63 		{
  64 			int o = orders[i];
  65 			if (o < 0) throw new ArgumentException($"slot {(SpecialSlot)i}: level-up order can't be negative");
  66 			bool levelled = _slots[i] is { } s && s.Level > 1;
