		Assert.Equal(1, r.Level, "Lv 1 (A3)");
		Assert.True(!d.Pick(0).Ok, "one pick per draft");

		foreach (var (scheme, seq) in new[] { (ControlScheme.Kata, "2 1 4+LP"), (ControlScheme.Kihon, "4+S") })
		{
			var m = NextMatch(run, scheme);
