		Assert.Equal("A,B", string.Join(",", card.Targets.Select(t => t.Slot)), "player may pick either starter");
		Assert.True(card.Targets[0].Frames.Contains("recovery 30 → 26"), $"Spirit Wave Lv 2 text from data: {card.Targets[0].Frames}");
